               'glob', 'rglob', 'iterdir', 'write_text', 'write_bytes', 'exec', 'eval'}

    def visit(node, prefix=''):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
